WITH metrics AS (SELECT id, name, email, country, signup_date, is_active, age, FIRST_VALUE(city) IGNORE NULLS OVER (PARTITION BY segment, country ORDER BY age, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_city, SUM(age) OVER (PARTITION BY segment, city ORDER BY credit_limit, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_age, CORR(age, credit_limit) OVER w_grp AS corr_age_credit_limit FROM customers WINDOW w_grp AS (PARTITION BY segment)) SELECT id, name, email, country, is_active, age, first_known_city, cumulative_age, CASE WHEN country RLIKE '^(SG|US)$' THEN 'CORE' ELSE 'GROUP_B' END AS country_zone FROM metrics ORDER BY country_zone DESC NULLS LAST;
